package com.borgpharmacy.pro.core.printer
import android.graphics.*
import com.borgpharmacy.pro.domain.model.*
class ThermalReceiptCanvas { fun render(facility:FacilityProfile,rep:Representative,company:Company,visit:Visit,logo:Bitmap?=null):Bitmap { val b=Bitmap.createBitmap(576,850,Bitmap.Config.ARGB_8888); val c=Canvas(b);c.drawColor(Color.WHITE);val p=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.BLACK;textAlign=Paint.Align.CENTER};var y=45f;logo?.let{c.drawBitmap(it,null,Rect(216,10,360,100),p);y=120f};p.textSize=28f;p.typeface=Typeface.DEFAULT_BOLD;c.drawText(facility.arabicName,288f,y,p);y+=35;c.drawText(facility.englishName,288f,y,p);y+=45;p.textAlign=Paint.Align.LEFT;p.textSize=26f;p.typeface=Typeface.DEFAULT;c.drawText("Representative: ${rep.name}",18f,y,p);y+=38;c.drawText("Company: ${company.name}",18f,y,p);y+=55;p.textAlign=Paint.Align.CENTER;p.textSize=40f;p.typeface=Typeface.DEFAULT_BOLD;c.drawText("${visit.date}  ${visit.shift.arabicName}",288f,y,p);y+=65;p.textSize=20f;c.drawText("Valid schedule receipt",288f,y,p);return b} }
